// Package stdlib embeds the PHP standard library signatures: the
// `*.stub.php` files of php-src's newest supported release branch (see
// php-src/LICENSE), the version table that says which release added each
// symbol (versions.go), and Phaenon's overlay that refines the stubs with
// the types PHP cannot express natively.
//
// php-src/, versions_gen.go and constants.php are generated by stdlib/gen
// from a php-src clone (`go generate ./stdlib`, see the gen command) and
// are byte-sensitive: never edit or reformat them by hand.
package stdlib

import (
	"embed"
	"io/fs"
	"sort"
	"strings"
	"sync"
)

//go:embed all:php-src
var phpSrc embed.FS

//go:embed all:overlay
var overlay embed.FS

//go:embed all:runtime
var runtime embed.FS

//go:embed all:concurrent
var concurrent embed.FS

//go:embed all:suggested
var suggested embed.FS

//go:embed constants.php
var constants []byte

//go:embed benevolent.txt
var benevolentList string

var benevolent = sync.OnceValue(func() map[string]bool {
	m := map[string]bool{}
	for _, line := range strings.Split(benevolentList, "\n") {
		if line = strings.TrimSpace(line); line != "" && !strings.HasPrefix(line, "#") {
			m[line] = true
		}
	}
	return m
})

// Benevolent reports a function or method (`class::method`, lower-cased)
// whose result PHPStan reads as a benevolent union: a method may be called
// on it when one of its members has it, as on phpredis's results in a
// pipeline or DOMDocument::createElement()'s.
func Benevolent(name string) bool { return benevolent()[name] }

// Constants returns the values of the constants php-src's stubs leave
// UNKNOWN, read once from PHP for the embedded extensions.
func Constants() []byte { return constants }

// Stub is one embedded signature file.
type Stub struct {
	Path string // e.g. "php-src/ext/standard/basic_functions.stub.php"
	Src  []byte
}

// Stubs returns every php-src stub, in a stable order.
func Stubs() []Stub {
	return walk(phpSrc, "php-src", ".stub.php")
}

// Overlay returns Phaenon's overlay files, which are read after the stubs
// and replace the signatures they redeclare.
func Overlay() []Stub {
	return walk(overlay, "overlay", ".php")
}

// EmbeddedExtensions names the extensions whose stubs are embedded, as
// get_loaded_extensions() spells them lower-cased ("core", "standard",
// "spl", "pdo_odbc"); the rest of a php's extensions are read from its
// reflection (program.LoadExtensions).
func EmbeddedExtensions() map[string]bool {
	out := map[string]bool{"core": true}
	entries, err := fs.ReadDir(phpSrc, "php-src/ext")
	if err != nil {
		return out
	}
	for _, e := range entries {
		if e.IsDir() {
			out[e.Name()] = true
		}
	}
	return out
}

// Runtime returns the declarations of the phaenon/runtime package, the
// stdlib written in Phaenon (`\Phaenon\Bytes`, the `Phaenon\Debug`
// line-map support). A file's path below runtime/ is its path below the
// package's src/.
func Runtime() []Stub {
	return append(walk(runtime, "runtime", ".php"), walk(runtime, "runtime", ".phn")...)
}

// Concurrent returns the declarations of the phaenon/concurrent package
// (`\Phaenon\Concurrent\Scope`, written in Phaenon) and of the amp v3 and
// Revolt API it is built on, which compiled `concurrently` blocks depend on.
func Concurrent() []Stub {
	return append(walk(concurrent, "concurrent", ".php"), walk(concurrent, "concurrent", ".phn")...)
}

// Suggested returns Phaenon's declarations of the libraries phaenon/runtime
// suggests — Monolog 3 and the Sentry SDK 4 — limited to the API its
// integrations in runtime/Debug are written against. Unlike Runtime and
// Concurrent they never enter a project's program (program.LoadStubs): a
// project that logs with Monolog has the real library in its vendor
// directory, and an embedded declaration would shadow it, as the amp
// declarations shadow amphp/amp. Only the programs that check and compile
// the stdlib itself load them (program.LoadSuggested). The runtime
// package's PHPStan run, against the real libraries, is what keeps them
// honest.
func Suggested() []Stub {
	return walk(suggested, "suggested", ".php")
}

func walk(f embed.FS, root, suffix string) []Stub {
	var out []Stub
	fs.WalkDir(f, root, func(path string, d fs.DirEntry, err error) error {
		if err != nil || d.IsDir() || !strings.HasSuffix(path, suffix) {
			return nil
		}
		src, err := f.ReadFile(path)
		if err != nil {
			return nil
		}
		out = append(out, Stub{Path: path, Src: src})
		return nil
	})
	sort.Slice(out, func(i, j int) bool { return out[i].Path < out[j].Path })
	return out
}
